-- E-conomic v1.5 frontend OTA — cuentas por cobrar/pagar y alertas.
do $migration$
declare v_html text;v_new text;v_addon text;v_sha text;
begin
if exists(select 1 from public.app_releases where version_code=8 and version='1.5.0') then return; end if;
select html into v_html from public.app_releases where is_active order by version_code desc,id desc limit 1;
if v_html is null then raise exception 'No active frontend release found'; end if;
if strpos(v_html,'id="v15Script"')>0 then raise exception 'v1.5 frontend already present in source release'; end if;
v_addon := $v15$
<style id="v15Style">
.v15-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.v15-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:14px 0}.v15-kpi{background:var(--card2);border:1px solid var(--border);border-radius:12px;padding:12px}.v15-kpi span{display:block;font-size:9px;text-transform:uppercase;font-weight:900;color:var(--muted)}.v15-kpi strong{display:block;font-size:18px;margin-top:5px}.v15-alerts{display:grid;gap:7px;margin:10px 0 14px}.v15-alert{display:grid;grid-template-columns:auto 1fr auto;gap:9px;align-items:center;border:1px solid var(--border);background:var(--card2);border-radius:11px;padding:9px 11px;color:var(--text);text-align:left}.v15-alert.overdue{border-color:color-mix(in srgb,var(--red) 38%,var(--border));background:color-mix(in srgb,var(--red) 8%,var(--card))}.v15-alert.today,.v15-alert.soon{border-color:color-mix(in srgb,var(--orange) 34%,var(--border));background:color-mix(in srgb,var(--orange) 7%,var(--card))}.v15-alert-icon{font-size:18px}.v15-alert-title{font-size:11px;font-weight:900;display:block}.v15-alert-meta{font-size:9px;color:var(--muted);margin-top:2px;display:block}.v15-alert-amt{font-size:11px;font-weight:900}.v15-filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px;margin-bottom:10px}.v15-list{display:grid;gap:9px}.v15-account{border:1px solid var(--border);border-radius:13px;background:var(--card2);padding:13px}.v15-account.overdue{border-color:color-mix(in srgb,var(--red) 40%,var(--border))}.v15-account-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.v15-account-name{font-weight:900;font-size:13px}.v15-account-sub{font-size:10px;color:var(--muted);margin-top:3px}.v15-badges{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end}.v15-badge{font-size:9px;font-weight:900;border:1px solid var(--border);border-radius:999px;padding:4px 8px;background:var(--card)}.v15-badge.receivable{color:var(--green)}.v15-badge.payable,.v15-badge.overdue{color:var(--red)}.v15-badge.paid{color:var(--green)}.v15-badge.cancelled{color:var(--muted)}.v15-values{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:10px 0}.v15-val{background:var(--card);border:1px solid var(--border);border-radius:9px;padding:8px}.v15-val span{display:block;font-size:8px;color:var(--muted);font-weight:900}.v15-val strong{display:block;font-size:11px;margin-top:3px}.v15-progress{height:7px;border-radius:999px;background:var(--border);overflow:hidden}.v15-progress>div{height:100%;background:var(--green)}.v15-account-foot{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:9px}.v15-account-note{font-size:9px;color:var(--muted)}.v15-modal{position:fixed;inset:0;z-index:140;background:rgba(0,0,0,.68);display:flex;align-items:center;justify-content:center;padding:18px}.v15-modal-card{width:min(620px,100%);max-height:92vh;overflow:auto;background:var(--card);border:1px solid var(--border);border-radius:18px;padding:18px;box-shadow:0 25px 80px rgba(0,0,0,.35)}.v15-modal-card.wide{width:min(760px,100%)}.v15-modal-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;margin-bottom:14px}.v15-modal-head h2{margin:0}.v15-payments{display:grid;gap:7px;margin-top:10px}.v15-payment{display:flex;justify-content:space-between;gap:10px;align-items:center;background:var(--card2);border:1px solid var(--border);border-radius:10px;padding:9px 10px}.v15-payment strong{font-size:10px}.v15-payment small{display:block;color:var(--muted);font-size:9px;margin-top:2px}.v15-payment.voided{opacity:.55;text-decoration:line-through}.v15-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.v15-info{background:var(--card2);border:1px solid var(--border);border-radius:10px;padding:10px}.v15-info span{display:block;font-size:8px;color:var(--muted);font-weight:900}.v15-info strong{display:block;font-size:11px;margin-top:3px}.v15-settlement{display:inline-flex;align-items:center;gap:5px;font-size:9px;font-weight:900;color:var(--primary);border:1px solid color-mix(in srgb,var(--primary) 30%,var(--border));border-radius:999px;padding:4px 7px;margin-top:5px}
@media(max-width:850px){.v15-kpis{grid-template-columns:1fr 1fr}.v15-filters{grid-template-columns:1fr 1fr}.v15-filters input{grid-column:1/-1}.v15-values{grid-template-columns:1fr 1fr 1fr}}@media(max-width:600px){.v15-kpis,.v15-detail-grid{grid-template-columns:1fr 1fr}.v15-values{grid-template-columns:1fr}.v15-account-top,.v15-account-foot{flex-direction:column}.v15-badges{justify-content:flex-start}.v15-modal{padding:7px}.v15-modal-card{padding:14px;border-radius:14px}.v15-alert{grid-template-columns:auto 1fr}.v15-alert-amt{grid-column:2}.v15-filters{grid-template-columns:1fr}}
</style>
<script id="v15Script">
(function(){
let v15Obligations=[],v15Payments=[],v15Channel=null,v15Ready=false,v15EditId=null,v15DetailId=null,v15ToastShown=false,v15SettlementTxIds=new Set();const V15_STORE='finance_v15_filter_v1';const v15Pad=n=>String(n).padStart(2,'0');
function v15Today(d=new Date()){return d.getFullYear()+'-'+v15Pad(d.getMonth()+1)+'-'+v15Pad(d.getDate())}function v15Date(s){const p=String(s||'').split('-').map(Number);return p.length===3?new Date(p[0],p[1]-1,p[2]):new Date()}function v15DaysTo(s){const a=v15Date(v15Today()),b=v15Date(s);return Math.round((b-a)/86400000)}function v15Fmt(v,c){return c==='VES'?moneyVES(v):c==='USDC'?moneyUSDC(v):moneyUSD(v)}function v15Posted(id){return v15Payments.filter(p=>p.obligation_id===id&&p.status==='posted')}function v15Paid(o){return v15Posted(o.id).reduce((s,p)=>s+Number(p.applied_original||0),0)}function v15Remaining(o){return Math.max(0,Number(o.amount_original||0)-v15Paid(o))}function v15RemainingUsd(o){const total=Number(o.amount_original||0),rem=v15Remaining(o);return total>0?Number(o.usd_bcv||0)*(rem/total):0}function v15Active(o){return o.status!=='paid'&&o.status!=='cancelled'&&v15Remaining(o)>.000001}function v15Alert(o){if(!v15Active(o))return{type:'none',days:999,label:''};const d=v15DaysTo(o.due_date);if(d<0)return{type:'overdue',days:d,label:`Vencida hace ${Math.abs(d)} día${Math.abs(d)===1?'':'s'}`};if(d===0)return{type:'today',days:d,label:'Vence hoy'};if(d<=Number(o.alert_days||7))return{type:'soon',days:d,label:`Vence en ${d} día${d===1?'':'s'}`};return{type:'none',days:d,label:''}}function v15StatusLabel(o){if(o.status==='paid')return o.kind==='receivable'?'Cobrada':'Pagada';if(o.status==='cancelled')return'Anulada';if(o.status==='partial')return'Parcial';return'Pendiente'}function v15CanEdit(o){return membership?.role==='owner'||o?.created_by===user?.id}function v15PaymentCanVoid(p){return p.status==='posted'&&(membership?.role==='owner'||p.created_by===user?.id)}function v15CurrentRates(){return{bcv:Number(rates?.bcv)||0,airtm:Number(rates?.airtm)||0}}function v15Convert(amount,currency,bcv,airtm){if(typeof convert==='function')return convert(amount,currency,bcv,airtm);amount=Number(amount)||0;let usd=0,ves=0,usdc=0;if(currency==='VES'){ves=amount;usd=ves/bcv;usdc=ves/airtm}else if(currency==='USD'){usd=amount;ves=usd*bcv;usdc=ves/airtm}else{usdc=amount;ves=usdc*airtm;usd=ves/bcv}return{usd,ves,usdc}}function v15Applied(amount,currency,o){const r=v15CurrentRates();if(!(r.bcv>0&&r.airtm>0))return 0;const x=v15Convert(amount,currency,r.bcv,r.airtm);return o.original_currency==='VES'?x.ves:o.original_currency==='USD'?x.ves/r.bcv:x.ves/r.airtm}
function v15Build(){if(v15Ready||$('v15Accounts'))return;const anchor=$('v14Reports')||document.querySelector('#appScreen .grid');if(!anchor)return;const card=document.createElement('section');card.id='v15Accounts';card.className='card';card.innerHTML=`<div class="v15-top"><div><h2 style="margin:0">Cuentas por cobrar y pagar</h2><div class="muted">Saldos pendientes, vencimientos, abonos parciales y alertas</div></div><button id="v15New" class="btn btn-primary" type="button">+ Nueva cuenta</button></div><div class="v15-kpis"><div class="v15-kpi"><span>Por cobrar</span><strong id="v15Receivable" class="green">$0.00</strong></div><div class="v15-kpi"><span>Por pagar</span><strong id="v15Payable" class="red">$0.00</strong></div><div class="v15-kpi"><span>Vencidas</span><strong id="v15Overdue">0</strong></div><div class="v15-kpi"><span>Próximas</span><strong id="v15Soon">0</strong></div></div><div id="v15Alerts" class="v15-alerts"></div><div class="v15-filters"><input id="v15Search" placeholder="Buscar cliente, proveedor, referencia…"><select id="v15Kind"><option value="">Cobrar y pagar</option><option value="receivable">Por cobrar</option><option value="payable">Por pagar</option></select><select id="v15State"><option value="active">Pendientes</option><option value="">Todas</option><option value="overdue">Vencidas</option><option value="soon">Próximas</option><option value="paid">Pagadas/cobradas</option><option value="cancelled">Anuladas</option></select></div><div id="v15List" class="v15-list"></div>`;anchor.parentNode.insertBefore(card,anchor);const edit=document.createElement('div');edit.id='v15EditModal';edit.className='v15-modal hidden';edit.innerHTML=`<div class="v15-modal-card"><div class="v15-modal-head"><div><h2 id="v15EditTitle">Nueva cuenta</h2><div class="muted">La cuenta no afecta el saldo hasta registrar un cobro o pago.</div></div><button id="v15EditClose" class="icon-btn" type="button">×</button></div><form id="v15Form"><div class="form-row"><div class="form-group"><label>Tipo</label><select id="v15FormKind"><option value="receivable">Cuenta por cobrar</option><option value="payable">Cuenta por pagar</option></select></div><div class="form-group"><label>Cliente / proveedor</label><input id="v15Counterparty" maxlength="160" required placeholder="Nombre"></div></div><div class="form-row"><div class="form-group"><label>Contacto</label><input id="v15Contact" maxlength="200" placeholder="Teléfono, correo…"></div><div class="form-group"><label>Referencia</label><input id="v15Reference" maxlength="200" placeholder="Factura, orden…"></div></div><div class="form-group"><label>Descripción</label><input id="v15Description" maxlength="500" placeholder="Concepto de la cuenta"></div><div class="form-group"><label>Notas</label><textarea id="v15Notes" maxlength="3000" placeholder="Condiciones, acuerdos, observaciones…"></textarea></div><div class="form-row"><div class="form-group"><label>Categoría</label><input id="v15Category" list="v15CategoryList" maxlength="120" placeholder="Otros"><datalist id="v15CategoryList"></datalist></div><div class="form-group"><label>Alertar con anticipación</label><select id="v15AlertDays"><option value="0">Solo al vencer</option><option value="3">3 días</option><option value="7" selected>7 días</option><option value="15">15 días</option><option value="30">30 días</option></select></div></div><div class="form-row"><div class="form-group"><label>Monto</label><input id="v15Amount" type="number" min="0.01" step="0.01" inputmode="decimal" required></div><div class="form-group"><label>Moneda de la cuenta</label><select id="v15Currency"><option value="USD">USD</option><option value="VES">VES</option><option value="USDC">USDC</option></select></div></div><div class="form-row"><div class="form-group"><label>Fecha de emisión</label><input id="v15Issue" type="date" required></div><div class="form-group"><label>Vencimiento</label><input id="v15Due" type="date" required></div></div><div id="v15FormHelp" class="snapshot"></div><div class="actions" style="margin-top:12px"><button id="v15Save" class="btn btn-primary" type="submit">Guardar cuenta</button><button id="v15Delete" class="btn btn-danger hidden" type="button">Eliminar</button></div></form></div>`;document.body.appendChild(edit);const detail=document.createElement('div');detail.id='v15DetailModal';detail.className='v15-modal hidden';detail.innerHTML=`<div class="v15-modal-card wide"><div class="v15-modal-head"><div><h2 id="v15DetailTitle">Cuenta</h2><div id="v15DetailSub" class="muted"></div></div><button id="v15DetailClose" class="icon-btn" type="button">×</button></div><div id="v15DetailSummary"></div><div id="v15PaymentBox"><h2 style="font-size:14px;margin-top:16px">Registrar cobro / pago</h2><div class="form-row"><div class="form-group"><label>Monto recibido/pagado</label><input id="v15PayAmount" type="number" min="0.01" step="0.01" inputmode="decimal"></div><div class="form-group"><label>Moneda real</label><select id="v15PayCurrency"><option value="USD">USD</option><option value="VES">VES</option><option value="USDC">USDC</option></select></div></div><div class="form-row"><div class="form-group"><label>Fecha</label><input id="v15PayDate" type="date"></div><div class="form-group"><label>Nota</label><input id="v15PayNote" maxlength="500" placeholder="Transferencia, efectivo…"></div></div><div id="v15PayPreview" class="snapshot"></div><div class="actions" style="margin-top:10px"><button id="v15PostPayment" class="btn btn-primary" type="button">Registrar</button><button id="v15EditAccount" class="btn btn-secondary" type="button">Editar cuenta</button><button id="v15CancelAccount" class="btn btn-danger" type="button">Anular cuenta</button></div></div><h2 style="font-size:14px;margin-top:18px">Historial de abonos</h2><div id="v15Payments" class="v15-payments"></div></div>`;document.body.appendChild(detail);$('v15New').onclick=()=>v15OpenEdit();$('v15EditClose').onclick=v15CloseEdit;$('v15DetailClose').onclick=v15CloseDetail;edit.addEventListener('click',e=>{if(e.target===edit)v15CloseEdit()});detail.addEventListener('click',e=>{if(e.target===detail)v15CloseDetail()});$('v15Form').onsubmit=v15SaveAccount;$('v15Delete').onclick=v15DeleteAccount;$('v15PostPayment').onclick=v15PostPayment;$('v15EditAccount').onclick=()=>{const id=v15DetailId;v15CloseDetail();v15OpenEdit(id)};$('v15CancelAccount').onclick=v15CancelAccount;['v15PayAmount','v15PayCurrency'].forEach(id=>$(id).addEventListener('input',v15RenderPayPreview));['v15Search','v15Kind','v15State'].forEach(id=>$(id).addEventListener('input',v15Render));try{const s=JSON.parse(localStorage.getItem(V15_STORE)||'{}');if(s.kind)$('v15Kind').value=s.kind;if(s.state!==undefined)$('v15State').value=s.state}catch(e){}v15Ready=true}
function v15Filtered(){const q=($('v15Search')?.value||'').trim().toLowerCase(),kind=$('v15Kind')?.value||'',state=$('v15State')?.value||'';try{localStorage.setItem(V15_STORE,JSON.stringify({kind,state}))}catch(e){}return v15Obligations.filter(o=>{const a=v15Alert(o),hay=[o.counterparty,o.contact,o.description,o.reference,o.notes,o.category,o.original_currency].join(' ').toLowerCase();let stateOk=true;if(state==='active')stateOk=v15Active(o);else if(state==='overdue')stateOk=a.type==='overdue';else if(state==='soon')stateOk=a.type==='today'||a.type==='soon';else if(state==='paid')stateOk=o.status==='paid';else if(state==='cancelled')stateOk=o.status==='cancelled';return(!q||hay.includes(q))&&(!kind||o.kind===kind)&&stateOk}).sort((a,b)=>{const aa=v15Alert(a),bb=v15Alert(b),rank=(o,x)=>x.type==='overdue'?0:x.type==='today'?1:x.type==='soon'?2:v15Active(o)?3:o.status==='paid'?4:5;return rank(a,aa)-rank(b,bb)||String(a.due_date).localeCompare(String(b.due_date))})}
function v15Render(){v15Build();if(!$('v15List'))return;let recv=0,pay=0,over=0,soon=0;v15Obligations.forEach(o=>{const rem=v15RemainingUsd(o),a=v15Alert(o);if(v15Active(o)){if(o.kind==='receivable')recv+=rem;else pay+=rem}if(a.type==='overdue')over++;if(a.type==='today'||a.type==='soon')soon++});$('v15Receivable').textContent=moneyUSD(recv);$('v15Payable').textContent=moneyUSD(pay);$('v15Overdue').textContent=String(over);$('v15Soon').textContent=String(soon);const alertRows=v15Obligations.map(o=>({o,a:v15Alert(o)})).filter(x=>x.a.type!=='none').sort((x,y)=>x.a.days-y.a.days).slice(0,5);$('v15Alerts').innerHTML=alertRows.length?alertRows.map(({o,a})=>`<button class="v15-alert ${a.type}" type="button" onclick="v15OpenDetail('${o.id}')"><span class="v15-alert-icon">${a.type==='overdue'?'⚠️':'🔔'}</span><span><span class="v15-alert-title">${esc(o.counterparty)}</span><span class="v15-alert-meta">${o.kind==='receivable'?'Por cobrar':'Por pagar'} · ${a.label} · ${formatDate(o.due_date)}</span></span><span class="v15-alert-amt">${v15Fmt(v15Remaining(o),o.original_currency)}</span></button>`).join(''):'';const data=v15Filtered();$('v15List').innerHTML=data.length?data.map(o=>{const paid=v15Paid(o),rem=v15Remaining(o),pct=Math.min(100,Number(o.amount_original)>0?paid/Number(o.amount_original)*100:0),a=v15Alert(o);return`<article class="v15-account ${a.type==='overdue'?'overdue':''}"><div class="v15-account-top"><div><div class="v15-account-name">${esc(o.counterparty)}</div><div class="v15-account-sub">${esc(o.description||o.reference||'Sin descripción')} · vence ${formatDate(o.due_date)}</div></div><div class="v15-badges"><span class="v15-badge ${o.kind}">${o.kind==='receivable'?'POR COBRAR':'POR PAGAR'}</span><span class="v15-badge ${a.type==='overdue'?'overdue':o.status}">${a.type==='overdue'?'VENCIDA':v15StatusLabel(o)}</span></div></div><div class="v15-values"><div class="v15-val"><span>ORIGINAL</span><strong>${v15Fmt(o.amount_original,o.original_currency)}</strong></div><div class="v15-val"><span>ABONADO</span><strong>${v15Fmt(paid,o.original_currency)}</strong></div><div class="v15-val"><span>PENDIENTE</span><strong>${v15Fmt(rem,o.original_currency)}</strong></div></div><div class="v15-progress"><div style="width:${pct}%"></div></div><div class="v15-account-foot"><span class="v15-account-note">${a.label||v15StatusLabel(o)}${o.reference?' · '+esc(o.reference):''}</span><div class="actions"><button class="btn btn-secondary" type="button" onclick="v15OpenDetail('${o.id}')">Ver / ${o.kind==='receivable'?'Cobrar':'Pagar'}</button>${v15CanEdit(o)&&o.status!=='cancelled'?`<button class="btn btn-secondary" type="button" onclick="v15OpenEdit('${o.id}')">Editar</button>`:''}</div></div></article>`}).join(''):'<div class="empty">No hay cuentas que coincidan con los filtros.</div>'}
async function v15Load(){if(!sb||!business)return;const[o,p]=await Promise.all([sb.from('obligations').select('*').eq('business_id',business.id).order('due_date',{ascending:true}),sb.from('obligation_payments').select('*').eq('business_id',business.id).order('paid_on',{ascending:false}).order('created_at',{ascending:false})]);if(o.error){console.warn('obligations',o.error);return}v15Obligations=o.data||[];v15Payments=p.error?[]:(p.data||[]);v15SettlementTxIds=new Set(v15Payments.filter(x=>x.status==='posted'&&x.transaction_id).map(x=>x.transaction_id));v15Render();try{renderTransactions()}catch(e){}if(!v15ToastShown){const ov=v15Obligations.filter(x=>v15Alert(x).type==='overdue').length,so=v15Obligations.filter(x=>['today','soon'].includes(v15Alert(x).type)).length;if(ov||so)toast(`${ov?ov+' vencida'+(ov===1?'':'s'):''}${ov&&so?' · ':''}${so?so+' próxima'+(so===1?'':'s'):''}`);v15ToastShown=true}}function v15Subscribe(){if(v15Channel&&sb){sb.removeChannel(v15Channel);v15Channel=null}if(!sb||!business)return;v15Channel=sb.channel('accounts-'+business.id).on('postgres_changes',{event:'*',schema:'public',table:'obligations',filter:`business_id=eq.${business.id}`},v15Load).on('postgres_changes',{event:'*',schema:'public',table:'obligation_payments',filter:`business_id=eq.${business.id}`},v15Load).subscribe()}
function v15CategoryOptions(){if($('v15CategoryList'))$('v15CategoryList').innerHTML=(categories||[]).map(c=>`<option value="${esc(c.name)}"></option>`).join('')}window.v15OpenEdit=function(id){v15Build();v15EditId=id||null;const o=id?v15Obligations.find(x=>x.id===id):null;$('v15EditTitle').textContent=o?'Editar cuenta':'Nueva cuenta';$('v15FormKind').value=o?.kind||'receivable';$('v15FormKind').disabled=!!o;$('v15Counterparty').value=o?.counterparty||'';$('v15Contact').value=o?.contact||'';$('v15Reference').value=o?.reference||'';$('v15Description').value=o?.description||'';$('v15Notes').value=o?.notes||'';$('v15Category').value=o?.category||'Otros';$('v15AlertDays').value=String(o?.alert_days??7);$('v15Amount').value=o?.amount_original||'';$('v15Currency').value=o?.original_currency||'USD';$('v15Issue').value=o?.issue_date||v15Today();const due=new Date();due.setDate(due.getDate()+7);$('v15Due').value=o?.due_date||v15Today(due);const hasPay=o?v15Posted(o.id).length>0:false;$('v15Amount').disabled=hasPay;$('v15Currency').disabled=hasPay;$('v15Delete').classList.toggle('hidden',!o||!v15CanEdit(o)||v15Payments.some(p=>p.obligation_id===o.id));$('v15FormHelp').textContent=hasPay?'Monto y moneda están bloqueados porque ya existen abonos. Puedes editar cliente, referencia, notas y vencimiento.':'La cuenta usa la tasa actual como referencia inicial; el saldo de caja solo cambia cuando registras un cobro o pago.';v15CategoryOptions();$('v15EditModal').classList.remove('hidden')};function v15CloseEdit(){$('v15EditModal')?.classList.add('hidden');v15EditId=null}async function v15SaveAccount(e){e.preventDefault();const o=v15EditId?v15Obligations.find(x=>x.id===v15EditId):null,r=o?{bcv:Number(o.bcv_rate),airtm:Number(o.airtm_rate)}:v15CurrentRates();if(!(r.bcv>0&&r.airtm>0)){toast('Actualiza las tasas antes de guardar');return}const common={p_counterparty:$('v15Counterparty').value.trim(),p_contact:$('v15Contact').value.trim(),p_description:$('v15Description').value.trim(),p_reference:$('v15Reference').value.trim(),p_notes:$('v15Notes').value.trim(),p_category:$('v15Category').value.trim()||'Otros',p_amount_original:Number($('v15Amount').value),p_original_currency:$('v15Currency').value,p_bcv_rate:r.bcv,p_airtm_rate:r.airtm,p_issue_date:$('v15Issue').value,p_due_date:$('v15Due').value,p_alert_days:Number($('v15AlertDays').value)};const btn=$('v15Save');btn.disabled=true;try{const res=o?await sb.rpc('update_obligation',{p_id:o.id,...common}):await sb.rpc('create_obligation',{p_business_id:business.id,p_kind:$('v15FormKind').value,...common});if(res.error)throw res.error;v15CloseEdit();await v15Load();await loadActivity();toast(o?'Cuenta actualizada':'Cuenta creada')}catch(err){toast(err?.message||'No se pudo guardar')}finally{btn.disabled=false}}async function v15DeleteAccount(){const o=v15Obligations.find(x=>x.id===v15EditId);if(!o)return;if(!confirm('¿Eliminar esta cuenta? Solo es posible si nunca tuvo abonos.'))return;const{error}=await sb.rpc('delete_obligation',{p_id:o.id});if(error){toast(error.message);return}v15CloseEdit();await v15Load();await loadActivity();toast('Cuenta eliminada')}
window.v15OpenDetail=function(id){v15Build();const o=v15Obligations.find(x=>x.id===id);if(!o)return;v15DetailId=id;$('v15DetailTitle').textContent=o.counterparty;$('v15DetailSub').textContent=(o.kind==='receivable'?'Cuenta por cobrar':'Cuenta por pagar')+' · '+v15StatusLabel(o);$('v15PayCurrency').value=o.original_currency;$('v15PayDate').value=v15Today();$('v15PayAmount').value=v15Remaining(o).toFixed(2);$('v15PayNote').value='';v15RenderDetail();$('v15DetailModal').classList.remove('hidden')};function v15CloseDetail(){$('v15DetailModal')?.classList.add('hidden');v15DetailId=null}function v15RenderDetail(){const o=v15Obligations.find(x=>x.id===v15DetailId);if(!o)return;const rem=v15Remaining(o),a=v15Alert(o),list=v15Payments.filter(p=>p.obligation_id===o.id);$('v15DetailSummary').innerHTML=`<div class="v15-detail-grid"><div class="v15-info"><span>TOTAL</span><strong>${v15Fmt(o.amount_original,o.original_currency)}</strong></div><div class="v15-info"><span>PENDIENTE</span><strong>${v15Fmt(rem,o.original_currency)}</strong></div><div class="v15-info"><span>VENCIMIENTO</span><strong>${formatDate(o.due_date)}</strong></div><div class="v15-info"><span>ESTADO</span><strong>${a.type==='overdue'?'Vencida · '+a.label:v15StatusLabel(o)}</strong></div></div>${o.reference?`<div class="snapshot"><strong>Referencia:</strong> ${esc(o.reference)}</div>`:''}${o.notes?`<div class="snapshot" style="margin-top:7px">${esc(o.notes)}</div>`:''}`;$('v15PaymentBox').classList.toggle('hidden',!v15Active(o));$('v15EditAccount').classList.toggle('hidden',!v15CanEdit(o));$('v15CancelAccount').classList.toggle('hidden',!v15CanEdit(o)||o.status==='paid'||o.status==='cancelled');$('v15Payments').innerHTML=list.length?list.map(p=>`<div class="v15-payment ${p.status==='voided'?'voided':''}"><div><strong>${v15Fmt(p.amount_original,p.original_currency)}${p.status==='voided'?' · ANULADO':''}</strong><small>${formatDate(p.paid_on)} · aplicado ${v15Fmt(p.applied_original,o.original_currency)}${p.note?' · '+esc(p.note):''}</small></div>${v15PaymentCanVoid(p)?`<button class="btn btn-link red" type="button" onclick="v15VoidPayment('${p.id}')">Anular</button>`:''}</div>`).join(''):'<div class="empty">Todavía no hay abonos.</div>';v15RenderPayPreview()}function v15RenderPayPreview(){const o=v15Obligations.find(x=>x.id===v15DetailId),el=$('v15PayPreview');if(!o||!el)return;const amt=Number($('v15PayAmount').value)||0,c=$('v15PayCurrency').value,r=v15CurrentRates(),ap=v15Applied(amt,c,o);el.textContent=r.bcv>0&&r.airtm>0?`Este ${o.kind==='receivable'?'cobro':'pago'} aplicará aproximadamente ${v15Fmt(ap,o.original_currency)} al saldo. Se creará también el movimiento de caja con las tasas actuales.`:'Actualiza las tasas antes de registrar el cobro/pago.'}async function v15PostPayment(){const o=v15Obligations.find(x=>x.id===v15DetailId);if(!o)return;const r=v15CurrentRates();if(!(r.bcv>0&&r.airtm>0)){toast('Actualiza las tasas antes de registrar');return}const btn=$('v15PostPayment');btn.disabled=true;try{const{error}=await sb.rpc('record_obligation_payment',{p_obligation_id:o.id,p_amount_original:Number($('v15PayAmount').value),p_original_currency:$('v15PayCurrency').value,p_bcv_rate:r.bcv,p_airtm_rate:r.airtm,p_paid_on:$('v15PayDate').value,p_note:$('v15PayNote').value.trim()});if(error)throw error;await Promise.all([v15Load(),loadTransactions(),loadActivity()]);v15RenderDetail();toast(o.kind==='receivable'?'Cobro registrado':'Pago registrado')}catch(err){toast(err?.message||'No se pudo registrar')}finally{btn.disabled=false}}window.v15VoidPayment=async function(id){const p=v15Payments.find(x=>x.id===id);if(!p)return;const reason=prompt('Motivo de la anulación del abono:','Corrección');if(reason===null)return;const{error}=await sb.rpc('void_obligation_payment',{p_payment_id:id,p_reason:reason});if(error){toast(error.message);return}await Promise.all([v15Load(),loadTransactions(),loadActivity()]);if(v15DetailId)v15RenderDetail();toast('Abono anulado')};async function v15CancelAccount(){const o=v15Obligations.find(x=>x.id===v15DetailId);if(!o)return;const reason=prompt('Motivo para anular esta cuenta:','');if(reason===null)return;const{error}=await sb.rpc('cancel_obligation',{p_id:o.id,p_reason:reason});if(error){toast(error.message);return}await v15Load();await loadActivity();v15RenderDetail();toast('Cuenta anulada')}
v15Build();const v15OldCanManage=canManageTx;canManageTx=function(t){if(v15SettlementTxIds.has(t?.id))return false;return v15OldCanManage(t)};const v15OldRenderTx=renderTransactions;renderTransactions=function(){v15OldRenderTx();const root=$('transactions');if(!root)return;const data=filtered(),cards=Array.from(root.querySelectorAll('article.tx'));cards.forEach((card,i)=>{const t=data[i];if(!t||!v15SettlementTxIds.has(t.id))return;const meta=card.querySelector('.tx-desc');if(meta&&!card.querySelector('.v15-settlement'))meta.insertAdjacentHTML('beforeend','<div class="v15-settlement">Vinculado a cuenta por cobrar/pagar</div>')})};const v15OldCleanup=cleanupRealtime;cleanupRealtime=function(){if(v15Channel&&sb){sb.removeChannel(v15Channel);v15Channel=null}return v15OldCleanup()};const v15OldRoute=routeAfterAuth;routeAfterAuth=async function(){await v15OldRoute();if(business){v15Build();await v15Load();v15Subscribe()}};const v15OldActivityTitle=activityTitle;activityTitle=function(a){const cp=a?.metadata?.counterparty?` · ${esc(a.metadata.counterparty)}`:'';if(a.action==='RECEIVABLE_CREATED')return`${activityActor(a)} creó una cuenta por cobrar${cp}`;if(a.action==='PAYABLE_CREATED')return`${activityActor(a)} creó una cuenta por pagar${cp}`;if(a.action==='OBLIGATION_UPDATED')return`${activityActor(a)} actualizó una cuenta${cp}`;if(a.action==='OBLIGATION_CANCELLED')return`${activityActor(a)} anuló una cuenta${cp}`;if(a.action==='OBLIGATION_DELETED')return`${activityActor(a)} eliminó una cuenta${cp}`;if(a.action==='RECEIVABLE_PAYMENT')return`${activityActor(a)} registró un cobro${cp}`;if(a.action==='PAYABLE_PAYMENT')return`${activityActor(a)} registró un pago${cp}`;if(a.action==='OBLIGATION_PAYMENT_VOIDED')return`${activityActor(a)} anuló un abono${cp}`;return v15OldActivityTitle(a)};const v15OldRenderActivity=renderActivity;renderActivity=function(){v15OldRenderActivity();const items=Array.from($('activityList')?.querySelectorAll('.activity-item')||[]);items.forEach((el,i)=>{const a=activityLogs[i];if(!a)return;const ic=el.querySelector('.activity-icon');if(!ic)return;if(a.action==='RECEIVABLE_CREATED')ic.textContent='📥';else if(a.action==='PAYABLE_CREATED')ic.textContent='📤';else if(a.action==='RECEIVABLE_PAYMENT'||a.action==='PAYABLE_PAYMENT')ic.textContent='💵';else if(a.action==='OBLIGATION_PAYMENT_VOIDED')ic.textContent='↩';else if(a.action==='OBLIGATION_UPDATED')ic.textContent='✎';else if(a.action==='OBLIGATION_CANCELLED')ic.textContent='⚠';else if(a.action==='OBLIGATION_DELETED')ic.textContent='🗑'})};$('reloadData')?.addEventListener('click',()=>setTimeout(v15Load,200));if(business){v15Load();v15Subscribe()}
})();
